// economy-engine 브라우저 번들 빌더.
// server/specialty.js + sim/economy-sim.js + sim/economy-sim-v2.js 를
// 브라우저용 단일 모듈(sim/economy-engine.browser.js)로 묶는다.
// require/module은 closure shim으로 처리, CLI(main)는 require.main 가드로 자동 비활성.
// 사용: node sim/build-econ-bundle.js  → 회귀검증: node sim/build-econ-bundle.js --check
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const rd = f => fs.readFileSync(path.join(root, f), 'utf8').replace(/^#!.*\n/, '');

const era = rd('server/era.js');          // ★[2026-08-01] 시대 게이트 — specialty 가 이걸 파생한다. 빠지면 랩이 폴백표로 조용히 갈린다.
const specialty = rd('server/specialty.js');
const econ1 = rd('sim/economy-sim.js');
const econ2 = rd('sim/economy-sim-v2.js');

const wrap = (name, body) =>
  `  modules[${JSON.stringify(name)}]=(function(){var module={exports:{}};var exports=module.exports;var require=req;\n${body}\n;return module.exports;})();\n`;

const bundle = `// AUTO-GENERATED by sim/build-econ-bundle.js — 직접 수정 금지.
// 소스: server/era.js + server/specialty.js + sim/economy-sim.js + sim/economy-sim-v2.js
;(function(root){
  var modules={};
  function req(p){ if(/era/.test(p))return modules.era; if(/specialty/.test(p))return modules.specialty; if(/economy-sim-v2/.test(p))return modules.v2; if(/economy-sim/.test(p))return modules.v1; return {}; }
${wrap('era', era)}${wrap('specialty', specialty)}${wrap('v1', econ1)}${wrap('v2', econ2)}
  root.EconEngine=Object.assign({},modules.v1,modules.v2); root.EconEngine.Era=modules.era;
})(typeof window!=='undefined'?window:globalThis);
`;

const outPath = path.join(root, 'sim/economy-engine.browser.js');
fs.writeFileSync(outPath, bundle);
console.log(`[build] economy-engine.browser.js 생성: ${(bundle.length / 1024).toFixed(0)} KB`);

// --check: 원본 모듈과 번들이 동일 시나리오서 정확히 일치하는지 회귀검증
if (process.argv.includes('--check')) {
  const Orig = require('./economy-sim-v2.js');
  delete require.cache[require.resolve(outPath)];
  require(outPath);
  const Bun = globalThis.EconEngine;
  const run = (Eng, seed, days) => {
    const w = Eng.createWorldV2({ seed, villageCount: 5, namePool: ['가','나','다','라','마'], infoRange: 5000, raidPer100: 0.005, picker: 'rational' });
    for (let d = 0; d < days; d++) Eng.tickWorldV2(w);
    return w.villages.map(v => `${v.name}:${v.npcs.length}/f${Math.floor(v.storage.food)}`).join(' ');
  };
  let pass = 0, fail = 0;
  for (const seed of [7, 42, 99, 1234]) for (const days of [150, 400]) {
    const ok = run(Orig, seed, days) === run(Bun, seed, days);
    ok ? pass++ : fail++;
  }
  console.log(`[check] 회귀검증 ${pass} 일치 / ${fail} 불일치` + (fail ? ' ❌' : ' ✅'));
  process.exit(fail ? 1 : 0);
}
